mkdir bootstrap && cd bootstrap
cat > versions.tf <<'EOF'
terraform {
  required_version = ">= 1.10.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
EOF
cat > variables.tf <<'EOF'
variable "region" {
  type    = string
  default = "eu-north-1"
}

# S3 bucket names are global. If you change this, change `bucket` in ../backend.tf to match.
variable "state_bucket_name" {
  type    = string
  default = "reports-terraform-state-eu-north-1"
}
EOF
cat > main.tf <<'EOF'
provider "aws" {
  region = var.region
}

# This configuration keeps its own state locally (it creates the remote backend, so it cannot use
# it). That state holds nothing sensitive; it is only needed to change or destroy the bucket.
resource "aws_s3_bucket" "state" {
  bucket = var.state_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

data "aws_iam_policy_document" "state" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}

# Old state versions can contain secrets; keep them for a while for recovery, then drop them.
resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "expire-noncurrent-state-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }

  depends_on = [aws_s3_bucket_versioning.state]
}
EOF
cat > outputs.tf <<'EOF'
output "state_bucket" {
  value = aws_s3_bucket.state.id
}
EOF
cd ..
cat > backend.tf <<'EOF'
# The bucket is created by ./bootstrap. Backend blocks cannot use variables, so keep the bucket
# name in sync with `state_bucket_name` there.
terraform {
  backend "s3" {
    bucket       = "reports-terraform-state-eu-north-1"
    key          = "reports/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    use_lockfile = true
  }
}
EOF
cat > .gitignore <<'EOF'
.terraform/
*.tfstate
*.tfstate.*
*.tfplan
crash.log
EOF
cat > README.md <<'EOF'
# reports

Terraform for the reports bucket and the key the nightly export job uploads with. The job reads
the key from `terraform output`.

## State

State lives in S3 (`reports-terraform-state-eu-north-1`, key `reports/terraform.tfstate`), with
versioning, encryption, and native S3 locking (`use_lockfile`, needs Terraform >= 1.10), so only one
`apply` runs at a time. The state contains the uploader's secret access key, so grant bucket
access only to people who may already read that secret.

Each engineer needs AWS credentials with `s3:ListBucket` on the bucket and `s3:GetObject`,
`s3:PutObject` and `s3:DeleteObject` on `reports/*` (the lock file is `reports/terraform.tfstate.tflock`).

## Usage

```sh
terraform init
terraform plan
terraform apply
```

## One-time setup (once per team)

1. Create the state bucket. `bootstrap/` keeps its own local state, which holds no secrets:

   ```sh
   terraform -chdir=bootstrap init
   terraform -chdir=bootstrap apply
   ```

   The bucket name is global; if it is taken, change `state_bucket_name` in `bootstrap/variables.tf`
   and `bucket` in `backend.tf`.

2. Migrate the existing local state. Run this on the laptop that has `terraform.tfstate`:

   ```sh
   terraform init -migrate-state
   terraform plan   # should show no changes
   ```

3. Once the plan is clean, delete the local `terraform.tfstate*` files (they contain the secret key)
   and commit `backend.tf`. Everyone else just runs `terraform init`.

Keep `bootstrap/terraform.tfstate` somewhere safe (or commit nothing and re-import) if you need to
change the bucket later; the bucket has `prevent_destroy` set.
EOF
which terraform && terraform fmt -check -recursive . ; terraform -chdir=bootstrap init -backend=false >/dev/null && terraform -chdir=bootstrap validate

